 ['the standard library parser finds the elements, attributes and texts of example3.html', 'EXAMPLE3 = \'<!-- This is an HTML comment. -->\\n\\n<html>\\n<head>\\n    <title>Example Website Title</title>\\n    <style>\\n        .slogan {\\n            color: gray;\\n            font-size: 2em;\\n        }\\n    </style>\\n</head>\\n<body>\\n    <h1>Example Website</h1>\\n    <p>This &lt;p&gt; tag puts <b>content</b> into a <i>single</i> paragraph.</p>\\n    <p><a href="https://inventwithpython.com">This text is a link</a> to books by <span id="author">Al Sweigart</span>.</p>\\n    <p><img src="wow_such_zophie_thumb.webp" alt="Close up of my cat Zophie." /></p>\\n    <p class="slogan">Learn to program in Python!</p>\\n    <form>\\n        <p><label>Username: <input id="login_user" placeholder="admin" /></label></p>\\n        <p><label>Password: <input id="login_pass" type="password" placeholder="swordfish" /></label></p>\\n        <p><label>Agree to disagree: <input type="checkbox" /></label><input type="submit" value="Fake Button" /></p>\\n    </form>\\n</body>\\n</html>\'\nfrom html.parser import HTMLParser\nVOID = {\'img\', \'input\', \'br\', \'meta\', \'link\', \'hr\'}\nclass Tree(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.stack = []; self.elements = []\n    def handle_starttag(self, tag, attrs):\n        el = {\'tag\': tag, \'attrs\': dict(attrs), \'text\': [], \'depth\': len(self.stack)}\n        self.elements.append(el)\n        if tag not in VOID: self.stack.append(el)\n    def handle_endtag(self, tag):\n        while self.stack and self.stack[-1][\'tag\'] != tag: self.stack.pop()\n        if self.stack: self.stack.pop()\n    def handle_data(self, data):\n        for el in self.stack: el[\'text\'].append(data)\nt = Tree(); t.feed(EXAMPLE3)\ndef text(el): return \'\'.join(el[\'text\'])\nprint(len(t.elements), [e[\'tag\'] for e in t.elements if e[\'tag\'] == \'p\'].__len__())\nauthor = [e for e in t.elements if e[\'attrs\'].get(\'id\') == \'author\']\nprint(len(author), author[0][\'attrs\'], text(author[0]))\nps = [e for e in t.elements if e[\'tag\'] == \'p\']\nprint(text(ps[0]))\nprint(text(ps[1]))\nprint(repr(text(ps[2])))\nprint([e[\'attrs\'].get(\'class\') for e in t.elements if \'class\' in e[\'attrs\']])\nprint([e[\'attrs\'][\'href\'] for e in t.elements if e[\'tag\'] == \'a\'])\nprint(len([e for e in t.elements if e[\'tag\'] == \'input\']), [e[\'attrs\'].get(\'type\', \'text\') for e in t.elements if e[\'tag\'] == \'input\'])\nprint(author[0][\'attrs\'].get(\'some_nonexistent_addr\') is None)\n', "26 7\n1 {'id': 'author'} Al Sweigart\nThis <p> tag puts content into a single paragraph.\nThis text is a link to books by Al Sweigart.\n''\n['slogan']\n['https://inventwithpython.com']\n4 ['text', 'password', 'checkbox', 'submit']\nTrue"],
