 ['robots.txt read with urllib.robotparser, and the wildcard of RFC 9309', 'import urllib.robotparser as rp\npypi = """User-agent: *\nDisallow: /simple/\nDisallow: /packages/\nDisallow: /search*\nDisallow: /account/\n"""\nr = rp.RobotFileParser(); r.parse(pypi.splitlines())\nfor u in (\'https://pypi.org/project/requests/\', \'https://pypi.org/simple/requests/\', \'https://pypi.org/search/?q=boring+stuff\', \'https://pypi.org/search*\'):\n    print(u, r.can_fetch(\'*\', u))\nxkcd = "User-agent: *\\nDisallow: /personal/\\n\\nUser-agent: GPTBot\\nDisallow: /\\n"\nr2 = rp.RobotFileParser(); r2.parse(xkcd.splitlines())\nprint(r2.can_fetch(\'*\', \'https://xkcd.com/1/\'), r2.can_fetch(\'GPTBot\', \'https://xkcd.com/1/\'), r2.can_fetch(\'*\', \'https://xkcd.com/personal/x\'))\nslow = "User-agent: *\\nCrawl-delay: 10\\nRequest-rate: 3/20\\nDisallow: /private\\n"\nr3 = rp.RobotFileParser(); r3.parse(slow.splitlines())\nprint(r3.crawl_delay(\'mybot\'), r3.request_rate(\'mybot\'), r3.can_fetch(\'mybot\', \'https://x.example/private/a\'))\nimport re\ndef rfc_match(pattern, path):\n    rx = re.escape(pattern).replace(r\'\\*\', \'.*\')\n    if rx.endswith(r\'\\$\'): rx = rx[:-2] + \'$\'\n    return re.match(rx, path) is not None\nprint(rfc_match(\'/search*\', \'/search/?q=boring+stuff\'), rfc_match(\'/this/path/exactly$\', \'/this/path/exactly\'), rfc_match(\'/this/path/exactly$\', \'/this/path/exactly/more\'))\n', 'https://pypi.org/project/requests/ True\nhttps://pypi.org/simple/requests/ False\nhttps://pypi.org/search/?q=boring+stuff True\nhttps://pypi.org/search* False\nTrue False False\n10 RequestRate(requests=3, seconds=20) False\nTrue True False'],
 ['searchpypi.py: the count of links to open, with a stub in place of the browser', 'import webbrowser\nfrom html.parser import HTMLParser\npage = \'\'\'<ul>\n<li><a class="package-snippet" href="/project/boring-one/"><h3>boring-one</h3></a></li>\n<li><a class="package-snippet" href="/project/boring-two/"><h3>boring-two</h3></a></li>\n<li><a class="other" href="/help/">Help</a></li>\n<li><a class="package-snippet" href="/project/boring-three/"><h3>boring-three</h3></a></li>\n</ul>\'\'\'\nclass Snippets(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.hrefs = []\n    def handle_starttag(self, tag, attrs):\n        a = dict(attrs)\n        if tag == \'a\' and \'package-snippet\' in (a.get(\'class\') or \'\').split(): self.hrefs.append(a[\'href\'])\ns = Snippets(); s.feed(page)\nopened = []\nclass Stub(webbrowser.BaseBrowser):\n    def open(self, url, new=0, autoraise=True): opened.append(url); return True\nwebbrowser.register(\'stub\', None, Stub(\'stub\'), preferred=True)\nnum_open = min(5, len(s.hrefs))\nfor i in range(num_open):\n    url_to_open = \'https://pypi.org\' + s.hrefs[i]\n    print(\'Opening\', url_to_open)\n    webbrowser.open(url_to_open)\nprint(num_open, len(opened), min(5, 0), min(5, 12))\n', 'Opening https://pypi.org/project/boring-one/\nOpening https://pypi.org/project/boring-two/\nOpening https://pypi.org/project/boring-three/\n3 3 0 5'],
 ['downloadXkcdComics.py: the loop, the stop at #, the page with no image, the ten-download limit', 'import http.server, os, tempfile, threading, urllib.request\nfrom html.parser import HTMLParser\nclass Page(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.in_comic = 0; self.src = None; self.prev = None\n    def handle_starttag(self, tag, attrs):\n        a = dict(attrs)\n        if tag == \'div\' and a.get(\'id\') == \'comic\': self.in_comic = 1\n        if tag == \'img\' and self.in_comic and self.src is None: self.src = a.get(\'src\')\n        if tag == \'a\' and a.get(\'rel\') == \'prev\': self.prev = a.get(\'href\')\n    def handle_endtag(self, tag):\n        if tag == \'div\': self.in_comic = 0\nSITE = {\n \'/\': \'<a rel="prev" href="/3/">Prev</a><div id="comic"><img src="//img.example/comics/three.png"></div>\',\n \'/3/\': \'<a rel="prev" href="/2/">Prev</a><div id="comic"><img src="//img.example/comics/two.png"></div>\',\n \'/2/\': \'<a rel="prev" href="/1/">Prev</a><div id="comic"><script>interactive()</script></div>\',\n \'/1/\': \'<a rel="prev" href="#">Prev</a><div id="comic"><img src="//img.example/comics/one.png"></div>\',\n}\nclass H(http.server.BaseHTTPRequestHandler):\n    def log_message(self, *a): pass\n    def do_GET(self):\n        body = SITE.get(self.path, \'\').encode(); self.send_response(200 if self.path in SITE else 404); self.end_headers(); self.wfile.write(body)\nsrv = http.server.ThreadingHTTPServer((\'127.0.0.1\', 0), H); threading.Thread(target=srv.serve_forever, daemon=True).start()\nroot = \'http://127.0.0.1:%d\' % srv.server_address[1]\ndef get(u):\n    with urllib.request.urlopen(u) as r: return r.read().decode()\ndef crawl(max_downloads):\n    url = root + \'/\'; n = 0; log = []; saved = []\n    while not url.endswith(\'#\') and n < max_downloads:\n        log.append(\'page \' + url.replace(root, \'SITE\'))\n        p = Page(); p.feed(get(url))\n        if p.src is None: log.append(\'no comic image\')\n        else:\n            comic_url = \'https:\' + p.src\n            saved.append(os.path.basename(comic_url))\n        url = root + p.prev; n += 1\n    return log, saved, url.replace(root, \'SITE\')\nfor limit in (10, 2):\n    log, saved, url = crawl(limit)\n    print(limit, saved, url); print(log)\nsrv.shutdown()\n', "10 ['three.png', 'two.png', 'one.png'] SITE#\n['page SITE/', 'page SITE/3/', 'page SITE/2/', 'no comic image', 'page SITE/1/']\n2 ['three.png', 'two.png'] SITE/2/\n['page SITE/', 'page SITE/3/']"],
 ['the Step 4 listing of the comic downloader as printed', 'book = """import requests, os, bs4, time\nurl = \'https://xkcd.com\'\nos.makedirs(\'xkcd\', exist_ok=True)\nnum_downloads = 0\nMAX_DOWNLOADS = 10\nwhile not url.endswith(\'#\') and num_downloads < MAX_DOWNLOADS:\n    res = requests.get(url)\n    soup = bs4.BeautifulSoup(res.text, \'html.parser\')\n    comic_elem = soup.select(\'#comic img\')\n    if comic_elem == []:\n        print(\'Could not find comic image.\')\n    else:\n        comic_URL = \'https:\' + comic_elem[0].get(\'src\')\n        res = requests.get(comic_URL)\n        res.raise_for_status()\n\n    # Save the image to ./xkcd.\n        image_file = open(os.path.join(\'xkcd\', os.path.basename(comic_URL)), \'wb\')\n            for chunk in res.iter_content(100000):\n               image_file.write(chunk)\n            image_file.close()\n\n    # Get the Prev button\'s URL.\n      prev_link = soup.select(\'a[rel="prev"]\')[0]\n      url = \'https://xkcd.com\' + prev_link.get(\'href\')\n      num_downloads += 1\n      time.sleep(1)  # Pause so we don\'t hammer the web server.\n"""\ntry:\n    compile(book, \'downloadXkcdComics.py\', \'exec\')\nexcept SyntaxError as e:\n    print(type(e).__name__ + \': \' + e.msg, \'line\', e.lineno)\nlines = [l for l in book.splitlines() if l.strip() and not l.lstrip().startswith(\'#\')]\ntail = lines[-10:]\nprint([len(l) - len(l.lstrip()) for l in tail])\nfixed = book.replace("            for chunk", "        for chunk").replace("               image_file.write", "            image_file.write").replace("            image_file.close()", "        image_file.close()").replace("      prev_link", "    prev_link").replace("      url = \'https://xkcd.com\' + prev", "    url = \'https://xkcd.com\' + prev").replace("      num_downloads", "    num_downloads").replace("      time.sleep", "    time.sleep")\ncompile(fixed, \'fixed\', \'exec\'); print(\'re-indented version compiles\')\n', 'IndentationError: unexpected indent line 19\n[8, 8, 8, 12, 15, 12, 6, 6, 6, 6]\nre-indented version compiles'],
 ['link verification: every a element, absolute and deduplicated, the 404s printed', 'import http.server, threading, urllib.error, urllib.parse, urllib.request\nfrom html.parser import HTMLParser\nPAGES = {\n \'/index.html\': \'<a href="/ok.html">fine</a> <a href="/gone.html">broken</a> <a href="https://other.example/x">elsewhere</a> <a href="/ok.html#top">again</a> <a href="mailto:a@b.example">mail</a> <a>no href</a>\',\n \'/ok.html\': \'<p>ok</p>\',\n}\nclass H(http.server.BaseHTTPRequestHandler):\n    def log_message(self, *a): pass\n    def do_GET(self):\n        self.send_response(200 if self.path in PAGES else 404); self.end_headers(); self.wfile.write(PAGES.get(self.path, \'missing\').encode())\nsrv = http.server.ThreadingHTTPServer((\'127.0.0.1\', 0), H); threading.Thread(target=srv.serve_forever, daemon=True).start()\nbase = \'http://127.0.0.1:%d\' % srv.server_address[1]\nclass Anchors(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.hrefs = []\n    def handle_starttag(self, tag, attrs):\n        if tag == \'a\' and dict(attrs).get(\'href\'): self.hrefs.append(dict(attrs)[\'href\'])\ndef status(url):\n    try:\n        with urllib.request.urlopen(url) as r: return r.status\n    except urllib.error.HTTPError as e: return e.code\na = Anchors(); a.feed(urllib.request.urlopen(base + \'/index.html\').read().decode())\nseen = set(); broken = []\nfor href in a.hrefs:\n    full = urllib.parse.urldefrag(urllib.parse.urljoin(base + \'/index.html\', href))[0]\n    if not full.startswith(base) or full in seen: continue\n    seen.add(full)\n    if status(full) == 404: broken.append(full.replace(base, \'SITE\'))\nprint(a.hrefs)\nprint(sorted(s.replace(base, \'SITE\') for s in seen))\nprint(\'broken:\', broken)\nsrv.shutdown()\n', "['/ok.html', '/gone.html', 'https://other.example/x', '/ok.html#top', 'mailto:a@b.example']\n['SITE/gone.html', 'SITE/ok.html']\nbroken: ['SITE/gone.html']"],
 ['a weather answer decoded: Kelvin, error shapes, the URL of the call, HTML where JSON was expected', 'import json\ntext = \'[{"name":"San Francisco","lat":37.7790262,"lon":-122.419906,"country":"US","state":"California"}]\'\ndata = json.loads(text)\nprint(type(data).__name__, data[0][\'lat\'], data[0][\'lon\'])\nweather = json.loads(\'{"coord":{"lon":-122.4199,"lat":37.779},"weather":[{"id":803,"main":"Clouds","description":"broken clouds"}],"main":{"temp":285.44,"feels_like":284.9,"humidity":78},"name":"San Francisco","cod":200}\')\nk = weather[\'main\'][\'temp\']\nprint(k, round(k - 273.15, 1), round(k * (9 / 5) - 459.67, 1))\nprint(weather[\'weather\'][0][\'main\'], weather[\'main\'][\'humidity\'])\nprint(json.loads(\'[]\') == [], json.loads(\'{"cod":"400","message":"wrong latitude"}\')[\'cod\'])\ncity, state, country, key = \'San Francisco\', \'CA\', \'US\', \'KEY\'\nprint(f\'https://api.openweathermap.org/geo/1.0/direct?q={city},{state},{country}&appid={key}\')\ntry:\n    json.loads(\'<html>Client Challenge</html>\')\nexcept json.JSONDecodeError as e:\n    print(type(e).__name__ + \': \' + str(e))\n', 'list 37.7790262 -122.419906\n285.44 12.3 54.1\nClouds 78\nTrue 400\nhttps://api.openweathermap.org/geo/1.0/direct?q=San Francisco,CA,US&appid=KEY\nJSONDecodeError: Expecting value: line 1 column 1 (char 0)'],
 ['the same timestamp in different time zones, and the deprecated utcfromtimestamp', "import datetime, warnings\nts = 1790000000.0\nprint(datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).isoformat())\nprint(datetime.datetime.fromtimestamp(ts, tz=datetime.timezone(datetime.timedelta(hours=3))).isoformat())\nwith warnings.catch_warnings(record=True) as w:\n    warnings.simplefilter('always'); datetime.datetime.utcfromtimestamp(ts)\nprint(w[0].category.__name__)\nimport os, time\nos.environ['TZ'] = 'Europe/Istanbul'; time.tzset(); a = datetime.datetime.fromtimestamp(ts)\nos.environ['TZ'] = 'America/Los_Angeles'; time.tzset(); b = datetime.datetime.fromtimestamp(ts)\nprint(a.isoformat(), b.isoformat(), a == b)\n", '2026-09-21T14:13:20+00:00\n2026-09-21T17:13:20+03:00\nDeprecationWarning\n2026-09-21T17:13:20 2026-09-21T07:13:20 False'],
